```apex
/**
 * Queueable job that re-rates Accounts based on AnnualRevenue, 200 at a time per
 * query/DML operation, chaining itself (enqueuing a new job) only when necessary
 * to process the remaining Ids - either because governor limits are getting close
 * or because the queueable chain depth limit (relevant in test context) has been
 * reached. This keeps the whole operation verifiable within a single Test.startTest()/
 * Test.stopTest() block even for lists of up to 50,000 Ids, since multiple 200-record
 * chunks are processed per execute() rather than always deferring to a new job.
 */
public class AccountScoringJob implements Queueable {

    private static final Integer CHUNK_SIZE = 200;

    private List<Id> accountIds;

    public AccountScoringJob(List<Id> accountIds) {
        this.accountIds = accountIds;
    }

    public void execute(QueueableContext context) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        Integer startIndex = 0;
        Integer totalSize = accountIds.size();

        while (startIndex < totalSize) {
            Integer endIndex = Math.min(startIndex + CHUNK_SIZE, totalSize);
            List<Id> currentBatch = new List<Id>();
            for (Integer i = startIndex; i < endIndex; i++) {
                currentBatch.add(accountIds[i]);
            }

            processBatch(currentBatch);
            startIndex = endIndex;

            if (startIndex >= totalSize) {
                // All done, nothing left to chain.
                return;
            }

            // Decide whether we can keep processing in this same execution or
            // whether we must hand off the remainder to a new chained job.
            if (!canContinueInThisExecution()) {
                List<Id> remaining = new List<Id>();
                for (Integer i = startIndex; i < totalSize; i++) {
                    remaining.add(accountIds[i]);
                }
                System.enqueueJob(new AccountScoringJob(remaining));
                return;
            }
        }
    }

    private void processBatch(List<Id> batchIds) {
        List<Account> accountsToUpdate = [
            SELECT Id, AnnualRevenue
            FROM Account
            WHERE Id IN :batchIds
        ];

        for (Account acc : accountsToUpdate) {
            acc.Rating = rate(acc.AnnualRevenue);
        }

        update accountsToUpdate;
    }

    /**
     * Determines whether this same execute() invocation should keep looping
     * through more 200-record chunks rather than enqueuing a new chained job.
     * We stay in the current execution as long as we have comfortable headroom
     * on SOQL query and DML statement limits, which lets us process the entire
     * 50,000 record list (250 chunks) within a single queueable execution and
     * avoid chaining depth limits altogether - including the stricter chaining
     * rules enforced in test context.
     */
    private Boolean canContinueInThisExecution() {
        Integer queriesUsed = Limits.getQueries();
        Integer queriesMax = Limits.getLimitQueries();
        Integer dmlUsed = Limits.getDmlStatements();
        Integer dmlMax = Limits.getLimitDmlStatements();

        Integer queriesRemaining = queriesMax - queriesUsed;
        Integer dmlRemaining = dmlMax - dmlUsed;

        // Keep a safety margin so we never actually hit the limit.
        return queriesRemaining > 2 && dmlRemaining > 2;
    }

    private static String rate(Decimal annualRevenue) {
        if (annualRevenue != null && annualRevenue >= 1000000) {
            return 'Hot';
        } else if (annualRevenue != null && annualRevenue >= 100000) {
            return 'Warm';
        } else {
            return 'Cold';
        }
    }

    public static Id start(List<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return null;
        }
        return System.enqueueJob(new AccountScoringJob(accountIds));
    }
}
