public with sharing class LineItemDiscountHandler {

    /**
     * For every line in the batch whose Discount is null, set it to the
     * standard discount for its product. Lines that already have a
     * Discount value (including 0) are left untouched.
     *
     * Bulk-safety note: PricingRules.standardDiscountFor(productId) runs a
     * SOQL query against Product2 internally. Calling it once per line (or
     * even once per distinct product) does not scale well and can blow the
     * query governor limit on large CPQ quotes (up to 200 lines).
     *
     * Instead, we query Product2.Family ourselves in a single bulk SOQL
     * query for all distinct products referenced by the batch, then use
     * PricingRules.standardDiscountForFamily(family) - which does no SOQL -
     * to resolve the discount for each line. This keeps the pricing logic
     * entirely owned by PricingRules (we never hardcode or copy discount
     * values/rules), while guaranteeing a single query for the whole
     * trigger invocation regardless of batch size.
     */
    public static void applyStandardDiscounts(List<OpportunityLineItem> lines) {
        // Collect distinct product Ids for lines that need a discount.
        Set<Id> productIdsNeedingDiscount = new Set<Id>();
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                productIdsNeedingDiscount.add(line.Product2Id);
            }
        }

        if (productIdsNeedingDiscount.isEmpty()) {
            return;
        }

        // Single bulk query to resolve each product's Family.
        Map<Id, String> familyByProductId = new Map<Id, String>();
        for (Product2 product : [
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIdsNeedingDiscount
        ]) {
            familyByProductId.put(product.Id, product.Family);
        }

        // Apply the discount to each line that still needs one, resolving
        // via the query-free PricingRules.standardDiscountForFamily method.
        for (OpportunityLineItem line : lines) {
            if (line.Discount == null && line.Product2Id != null) {
                String family = familyByProductId.get(line.Product2Id);
                line.Discount = PricingRules.standardDiscountForFamily(family);
            }
        }
    }
