public class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Collect ids needed
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId != null) {
                oppIds.add(req.opportunityId);
            }
            if (req.contactId != null) {
                contactIds.add(req.contactId);
            }
        }

        // Query 1: Opportunities with primary contact and amount
        Map<Id, Opportunity> oppById = new Map<Id, Opportunity>(
            [SELECT Id, Amount, npsp__Primary_Contact__c
             FROM Opportunity
             WHERE Id IN :oppIds]
        );

        // Validate before any DML
        for (SoftCreditRequest req : requests) {
            if (req.opportunityId == null || req.contactId == null) {
                throw new SoftCreditException('Opportunity Id and Contact Id are required.');
            }
            Opportunity opp = oppById.get(req.opportunityId);
            if (opp == null) {
                throw new SoftCreditException('Opportunity not found: ' + req.opportunityId);
            }
            if (opp.npsp__Primary_Contact__c == req.contactId) {
                throw new SoftCreditException(
                    'Contact ' + req.contactId + ' is the primary contact for Opportunity ' + req.opportunityId
                );
            }
            if (req.amount == null || req.amount <= 0) {
                throw new SoftCreditException('Amount must be a positive value.');
            }
            if (opp.Amount != null && req.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Amount ' + req.amount + ' exceeds Opportunity Amount for ' + req.opportunityId
                );
            }
        }

        // Query 2: Existing OpportunityContactRoles for these opp/contact pairs
        List<OpportunityContactRole> existingRoles = [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds AND ContactId IN :contactIds
        ];

        Map<String, OpportunityContactRole> rolesByKey = new Map<String, OpportunityContactRole>();
        for (OpportunityContactRole ocr : existingRoles) {
            String key = ocr.OpportunityId + ':' + ocr.ContactId;
            rolesByKey.put(key, ocr);
        }

        List<OpportunityContactRole> rolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToUpdate = new List<OpportunityContactRole>();

        // Determine which requests need a new role vs update vs reuse (role already matches)
        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + ':' + req.contactId;

            OpportunityContactRole existing = rolesByKey.get(key);
            if (existing == null) {
                OpportunityContactRole newRole = new OpportunityContactRole(
                    OpportunityId = req.opportunityId,
                    ContactId = req.contactId,
                    Role = req.role
                );
                rolesToInsert.add(newRole);
            } else if (existing.Role != req.role) {
                // Build a minimal, clean sobject with only Id and Role set
                // to avoid field-level issues with other fields on the queried record.
                OpportunityContactRole minimalUpdate = new OpportunityContactRole(
                    Id = existing.Id,
                    Role = req.role
                );
                rolesToUpdate.add(minimalUpdate);
                // Keep the in-memory map in sync with the new role value for later use.
                existing.Role = req.role;
            }
        }

        // DML 1: insert new contact roles
        if (!rolesToInsert.isEmpty()) {
            insert rolesToInsert;
        }
        // DML 2: update changed contact roles
        if (!rolesToUpdate.isEmpty()) {
            update rolesToUpdate;
        }

        // Build final map of OpportunityContactRole Id keyed by opp:contact,
        // combining existing (possibly updated) and newly inserted roles.
        for (OpportunityContactRole ocr : rolesToInsert) {
            String key = ocr.OpportunityId + ':' + ocr.ContactId;
            rolesByKey.put(key, ocr);
        }

        // Query 3: Existing Partial Soft Credits for these opp/contact pairs
        List<npsp__Partial_Soft_Credit__c> existingPscs = [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds AND npsp__Contact__c IN :contactIds
        ];

        Map<String, npsp__Partial_Soft_Credit__c> pscsByKey = new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : existingPscs) {
            String key = psc.npsp__Opportunity__c + ':' + psc.npsp__Contact__c;
            pscsByKey.put(key, psc);
        }

        List<npsp__Partial_Soft_Credit__c> pscsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> pscsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest req : requests) {
            String key = req.opportunityId + ':' + req.contactId;
            OpportunityContactRole ocr = rolesByKey.get(key);

            npsp__Partial_Soft_Credit__c existingPsc = pscsByKey.get(key);
            if (existingPsc == null) {
                npsp__Partial_Soft_Credit__c newPsc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = req.opportunityId,
                    npsp__Contact__c = req.contactId,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = ocr.Id
                );
                pscsToInsert.add(newPsc);
            } else {
                npsp__Partial_Soft_Credit__c minimalUpdate = new npsp__Partial_Soft_Credit__c(
                    Id = existingPsc.Id,
                    npsp__Amount__c = req.amount,
                    npsp__Role_Name__c = req.role,
                    npsp__Contact_Role_ID__c = ocr.Id
