/**
 * RecordAccessService
 *
 * Provides a bulk-safe way to determine which of a set of record Ids the
 * running user is actually permitted to edit, taking into account object
 * permissions, field-level security (not applicable here, this is row level),
 * ownership, sharing rules, role hierarchy, and View All / Modify All —
 * i.e. everything that UserRecordAccess.HasEditAccess already evaluates for us.
 *
 * The records referenced by recordIds may belong to different sObject types;
 * UserRecordAccess works across objects uniformly since it is keyed purely by
 * RecordId, so no per-object branching is required.
 */
public with sharing class RecordAccessService {

    // UserRecordAccess queries must be filtered on RecordId with a bounded IN clause.
    // 200 Ids per query is a safe, well within limits chunk size that keeps us
    // comfortably under the 20-query budget even for the maximum of 2,000 Ids
    // (2000 / 200 = 10 queries).
    @TestVisible
    private static final Integer CHUNK_SIZE = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> result = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return result;
        }

        // De-duplicate and drop nulls defensively; also establishes a stable
        // iteration order for chunking.
        List<Id> uniqueIds = new List<Id>();
        Set<Id> seen = new Set<Id>();
        for (Id recId : recordIds) {
            if (recId != null && !seen.contains(recId)) {
                seen.add(recId);
                uniqueIds.add(recId);
            }
        }

        if (uniqueIds.isEmpty()) {
            return result;
        }

        Integer totalChunks = Integer.valueOf(
            Math.ceil(Decimal.valueOf(uniqueIds.size()) / Decimal.valueOf(CHUNK_SIZE))
        );

        // Guard rail: with CHUNK_SIZE = 200 and a caller limit of 2,000 Ids,
        // this will never exceed 10 queries, well under the 20-query ceiling.
        // If callers somehow exceed the documented 2,000 Id contract, fail
        // fast rather than silently burning through the query limit.
        if (totalChunks > 20) {
            throw new RecordAccessServiceException(
                'Too many record Ids supplied (' + uniqueIds.size() +
                '). A maximum of ' + (20 * CHUNK_SIZE) + ' Ids is supported per call.'
            );
        }

        Integer startIndex = 0;
        while (startIndex < uniqueIds.size()) {
            Integer stopIndex = Math.min(startIndex + CHUNK_SIZE, uniqueIds.size());
            List<Id> chunk = new List<Id>();
            for (Integer i = startIndex; i < stopIndex; i++) {
                chunk.add(uniqueIds[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId, HasEditAccess
                FROM UserRecordAccess
                WHERE UserId = :UserInfo.getUserId()
                AND RecordId IN :chunk
            ]) {
                if (access.HasEditAccess) {
                    result.add(access.RecordId);
                }
            }

            startIndex = stopIndex;
        }

        return result;
    }

    public class RecordAccessServiceException extends Exception {}
}
